"""Real-question orchid reasoning benchmark: contract, validator and scorer.

This module holds no questions and no answers.  It defines what a case and its
independent expert review must contain before any system may be scored on it,
and refuses -- rather than repairs -- anything that would let ground truth be
manufactured:

* a question with no recorded real origin, or one generated by a model;
* an expected answer that did not come from at least
  ``MIN_INDEPENDENT_EXPERT_REVIEWS`` independent expert reviews;
* a label carried over from a fixture (``FIXTURE_CONSTRUCTION``);
* a reviewer citing a document the case does not list;
* a stored excerpt the source's rights state does not permit;
* heldout cases sharing source documents with development cases.

Reviewer disagreement is preserved, never averaged: a case whose reviewers do
not agree on the answer state is ``DISAGREEMENT`` and is scored separately
(did the system avoid a confident ``CANDIDATE``?), not counted as right or
wrong.  A run with no scorable case reports nothing and says so.

Rights states are #1182's vocabulary; review statuses are Brain KO-0024's;
answer states are SCIAN-002's ``InferenceState``.  ``to_evaluation_case``
emits the ``app.evals.EvaluationCase`` shape proposed in #1379-#1383 so the
set can move into that store once it lands.
"""

from __future__ import annotations

import json
import statistics
from collections.abc import Callable, Iterable, Mapping
from dataclasses import dataclass, field
from hashlib import sha256
from pathlib import Path
from typing import Any

from app.scientific_inference.models import InferenceState

from .benchmark import aggregate, score_case
from .contracts import Facet

BENCHMARK_VERSION = "oc-orchid-reasoning-real-v1"
REAL_BENCHMARK_DIR = Path(__file__).resolve().parents[2] / "benchmarks" / "orchid_reasoning_real"
TASK_CLASS_ID = "scientific-reasoning.graph-grounded"
MIN_INDEPENDENT_EXPERT_REVIEWS = 2
MAX_STORED_EXCERPT_CHARS = 300

CATEGORIES: frozenset[str] = frozenset(
    {
        "taxonomy_synonymy",
        "morphological_identification",
        "species_description",
        "pollination_biology",
        "mycorrhizal_associations",
        "geographic_distribution",
        "conflicting_literature",
        "uncertain_incomplete",
    }
)
QUESTION_ORIGINS: frozenset[str] = frozenset(
    {"member_submitted", "expert_authored", "literature_derived", "operational_log"}
)
#: #1182 rights vocabulary ("represent, never guess").
RIGHTS_STATES: frozenset[str] = frozenset(
    {
        "METADATA_ONLY",
        "PUBLIC_DOMAIN",
        "OPEN_LICENSE",
        "REPOSITORY_ACCEPTED_MANUSCRIPT",
        "HUMAN_READING_ONLY",
        "INTERNAL_TDM_PERMITTED",
        "REUSE_RESTRICTED",
        "MODEL_TRANSMISSION_RESTRICTED",
        "RIGHTS_UNKNOWN",
        "OWNER_REVIEW_REQUIRED",
    }
)
EXCERPT_PERMITTED_RIGHTS = frozenset({"PUBLIC_DOMAIN", "OPEN_LICENSE"})
MODEL_TRANSMISSION_PERMITTED_RIGHTS = frozenset({"PUBLIC_DOMAIN", "OPEN_LICENSE", "INTERNAL_TDM_PERMITTED"})
#: Brain KO-0024 review statuses; only ``expert_reviewed`` and
#: ``source_verified`` count towards a label.
REVIEW_STATUSES: frozenset[str] = frozenset(
    {
        "unreviewed",
        "submitted",
        "machine_assisted",
        "human_reviewed",
        "expert_reviewed",
        "source_verified",
        "uncertain",
        "conflicting_sources",
        "needs_followup",
        "public_ready",
        "restricted",
        "deprecated",
        "archived",
    }
)
LABEL_GRADE_REVIEW_STATUSES = frozenset({"expert_reviewed", "source_verified"})
ANSWER_STATES = frozenset(state.value for state in InferenceState)
SPLITS = frozenset({"dev", "heldout"})

SCORABLE = "SCORABLE"
DISAGREEMENT = "DISAGREEMENT"
INSUFFICIENT_REVIEW = "INSUFFICIENT_REVIEW"


@dataclass(frozen=True)
class CaseLabel:
    case_id: str
    status: str
    expected_state: str | None
    consensus_documents: tuple[str, ...]
    acceptable_documents: tuple[str, ...]
    conflict_documents: tuple[str, ...]
    reviewer_states: tuple[str, ...]
    independent_expert_reviews: int


@dataclass(frozen=True)
class ValidationReport:
    violations: tuple[str, ...]
    labels: dict[str, CaseLabel] = field(default_factory=dict)

    @property
    def valid(self) -> bool:
        return not self.violations

    def counts(self) -> dict[str, int]:
        out = {SCORABLE: 0, DISAGREEMENT: 0, INSUFFICIENT_REVIEW: 0}
        for label in self.labels.values():
            out[label.status] += 1
        return out


def _sources_by_id(suite: Mapping[str, Any]) -> dict[str, Mapping[str, Any]]:
    return {str(s.get("document_id")): s for s in suite.get("sources") or ()}


def _validate_source(source: Mapping[str, Any]) -> list[str]:
    sid = source.get("document_id")
    out: list[str] = []
    if not sid:
        return ["SOURCE_DOCUMENT_ID_MISSING"]
    if source.get("rights_state") not in RIGHTS_STATES:
        out.append(f"SOURCE_RIGHTS_STATE_UNKNOWN:{sid}")
    citation = source.get("citation") or {}
    for required in ("title", "author_or_creator", "publication_year"):
        if not citation.get(required):
            out.append(f"SOURCE_CITATION_INCOMPLETE:{sid}:{required}")
    if not (citation.get("url_or_identifier") or citation.get("citation_text")):
        out.append(f"SOURCE_CITATION_INCOMPLETE:{sid}:identifier")
    excerpt = source.get("excerpt")
    if excerpt is not None:
        if source.get("rights_state") not in EXCERPT_PERMITTED_RIGHTS:
            out.append(f"SOURCE_EXCERPT_NOT_PERMITTED:{sid}")
        elif len(str(excerpt)) > MAX_STORED_EXCERPT_CHARS:
            out.append(f"SOURCE_EXCERPT_TOO_LONG:{sid}")
        elif source.get("excerpt_sha256") != sha256(str(excerpt).encode()).hexdigest():
            out.append(f"SOURCE_EXCERPT_HASH_MISMATCH:{sid}")
    if not source.get("locator"):
        out.append(f"SOURCE_LOCATOR_MISSING:{sid}")
    return out


def _label(case: Mapping[str, Any], reviews: list[Mapping[str, Any]]) -> CaseLabel:
    grade = [r for r in reviews if r.get("independent") is True and r.get("review_status") in LABEL_GRADE_REVIEW_STATUSES]
    reviewers = {r.get("reviewer_id") for r in grade}
    states = tuple(str(r.get("answer_state")) for r in grade)
    supporting = [set(r.get("supporting_document_ids") or ()) for r in grade]
    contradicting = [set(r.get("contradicting_document_ids") or ()) for r in grade]
    consensus = set.intersection(*supporting) if supporting else set()
    acceptable = set.union(*supporting, *contradicting) if supporting else set()
    conflict = set.intersection(*contradicting) if contradicting else set()
    if len(reviewers) < MIN_INDEPENDENT_EXPERT_REVIEWS:
        status, expected = INSUFFICIENT_REVIEW, None
    elif len(set(states)) > 1:
        status, expected = DISAGREEMENT, None
    else:
        status, expected = SCORABLE, states[0]
    return CaseLabel(
        case_id=str(case.get("case_id")),
        status=status,
        expected_state=expected,
        consensus_documents=tuple(sorted(consensus)),
        acceptable_documents=tuple(sorted(acceptable)),
        conflict_documents=tuple(sorted(conflict | (consensus if expected == "CONFLICT_REVIEW_REQUIRED" else set()))),
        reviewer_states=states,
        independent_expert_reviews=len(reviewers),
    )


def validate_suite(suite: Mapping[str, Any]) -> ValidationReport:
    violations: list[str] = []
    if suite.get("benchmark_version") != BENCHMARK_VERSION:
        violations.append("BENCHMARK_VERSION_UNSUPPORTED")
    if suite.get("label_source") == "FIXTURE_CONSTRUCTION":
        violations.append("FIXTURE_LABELS_NOT_ALLOWED")
    sources = _sources_by_id(suite)
    for source in suite.get("sources") or ():
        violations.extend(_validate_source(source))
    reviews_by_case: dict[str, list[Mapping[str, Any]]] = {}
    for review in suite.get("reviews") or ():
        reviews_by_case.setdefault(str(review.get("case_id")), []).append(review)

    labels: dict[str, CaseLabel] = {}
    split_documents: dict[str, set[str]] = {"dev": set(), "heldout": set()}
    seen: set[str] = set()
    for case in suite.get("cases") or ():
        cid = str(case.get("case_id") or "")
        if not cid or cid in seen:
            violations.append(f"CASE_ID_MISSING_OR_DUPLICATE:{cid}")
            continue
        seen.add(cid)
        if case.get("category") not in CATEGORIES:
            violations.append(f"CASE_CATEGORY_UNKNOWN:{cid}")
        if case.get("facet") not in {f.value for f in Facet}:
            violations.append(f"CASE_FACET_UNKNOWN:{cid}")
        if not str(case.get("question") or "").strip():
            violations.append(f"CASE_QUESTION_MISSING:{cid}")
        origin = case.get("question_origin") or {}
        if origin.get("type") not in QUESTION_ORIGINS:
            violations.append(f"CASE_QUESTION_ORIGIN_INVALID:{cid}")
        if origin.get("model_generated") is not False:
            violations.append(f"CASE_QUESTION_MODEL_GENERATED_OR_UNDECLARED:{cid}")
        if not origin.get("recorded_at"):
            violations.append(f"CASE_QUESTION_ORIGIN_UNDATED:{cid}")
        if case.get("split") not in SPLITS:
            violations.append(f"CASE_SPLIT_INVALID:{cid}")
        if "expected_state" in case or "expected_documents" in case:
            violations.append(f"CASE_CARRIES_ITS_OWN_LABEL:{cid}")
        listed = set(case.get("source_document_ids") or ())
        for doc in listed - set(sources):
            violations.append(f"CASE_SOURCE_NOT_REGISTERED:{cid}:{doc}")
        if case.get("split") in SPLITS:
            split_documents[case["split"]] |= listed

        reviews = reviews_by_case.get(cid, [])
        reviewer_ids = [r.get("reviewer_id") for r in reviews]
        if len(reviewer_ids) != len(set(reviewer_ids)):
            violations.append(f"REVIEWER_DUPLICATED:{cid}")
        for review in reviews:
            rid = review.get("reviewer_id")
            if not rid or not review.get("qualification") or not review.get("reviewed_at"):
                violations.append(f"REVIEW_IDENTITY_INCOMPLETE:{cid}:{rid}")
            if review.get("answer_state") not in ANSWER_STATES:
                violations.append(f"REVIEW_ANSWER_STATE_INVALID:{cid}:{rid}")
            if review.get("review_status") not in REVIEW_STATUSES:
                violations.append(f"REVIEW_STATUS_INVALID:{cid}:{rid}")
            if review.get("model_assisted") is not False:
                violations.append(f"REVIEW_MODEL_ASSISTANCE_UNDECLARED_OR_TRUE:{cid}:{rid}")
            cited = set(review.get("supporting_document_ids") or ()) | set(review.get("contradicting_document_ids") or ())
            for doc in cited - listed:
                violations.append(f"REVIEW_CITES_UNLISTED_SOURCE:{cid}:{rid}:{doc}")
            if review.get("answer_state") != "INSUFFICIENT_EVIDENCE" and not review.get("supporting_document_ids"):
                violations.append(f"REVIEW_ANSWER_WITHOUT_SUPPORT:{cid}:{rid}")
        labels[cid] = _label(case, reviews)

    for doc in split_documents["dev"] & split_documents["heldout"]:
        violations.append(f"SPLIT_LEAKAGE_SHARED_SOURCE:{doc}")
    for orphan in set(reviews_by_case) - seen:
        violations.append(f"REVIEW_FOR_UNKNOWN_CASE:{orphan}")
    return ValidationReport(violations=tuple(violations), labels=labels)


def model_transmission_permitted(suite: Mapping[str, Any], case: Mapping[str, Any]) -> bool:
    """A case may go to an external model only if every listed source allows it."""

    sources = _sources_by_id(suite)
    return all(
        sources.get(doc, {}).get("rights_state") in MODEL_TRANSMISSION_PERMITTED_RIGHTS
        for doc in case.get("source_document_ids") or ()
    )


def to_evaluation_case(case: Mapping[str, Any], label: CaseLabel) -> dict[str, Any]:
    """The ``app.evals.EvaluationCase`` shape proposed in #1379-#1383."""

    return {
        "case_id": case["case_id"],
        "version": int(case.get("version", 1)),
        "task_class_id": TASK_CLASS_ID,
        "input_ref": f"{BENCHMARK_VERSION}:question:{case['case_id']}",
        "expected_ref": f"{BENCHMARK_VERSION}:adjudication:{case['case_id']}" if label.status == SCORABLE else None,
        "provenance": {
            "question_origin": dict(case.get("question_origin") or {}),
            "label_status": label.status,
            "independent_expert_reviews": label.independent_expert_reviews,
            "reviewer_states": list(label.reviewer_states),
            "split": case.get("split"),
        },
    }


AnswerFn = Callable[[Mapping[str, Any]], dict[str, Any]]


def score_suite(
    suite: Mapping[str, Any],
    systems: Mapping[str, AnswerFn],
    *,
    split: str = "heldout",
    external_model_systems: Iterable[str] = (),
) -> dict[str, Any]:
    """Score every system on the same validated, scorable cases.

    Each ``AnswerFn`` takes a case and returns ``{state, cited_documents,
    conflict_documents, latency_ms, provider_calls, cost_usd}``.  Systems named
    in ``external_model_systems`` are only given cases whose sources permit
    model transmission.  Refuses to score an invalid suite or an empty split.
    """

    report = validate_suite(suite)
    if not report.valid:
        return {"status": "REFUSED_INVALID_SUITE", "violations": list(report.violations)}
    cases = [c for c in suite.get("cases") or () if c.get("split") == split]
    scorable = [c for c in cases if report.labels[c["case_id"]].status == SCORABLE]
    disagreements = [c for c in cases if report.labels[c["case_id"]].status == DISAGREEMENT]
    if not scorable:
        return {
            "status": "REFUSED_NO_SCORABLE_CASES",
            "split": split,
            "label_counts": report.counts(),
            "detail": "No case in this split has the required independent expert agreement; no accuracy is reported.",
        }
    external = set(external_model_systems)
    results: dict[str, Any] = {}
    for name, answer in systems.items():
        rows, skipped, disagreement_rows, costs = [], [], [], []
        for case in scorable:
            if name in external and not model_transmission_permitted(suite, case):
                skipped.append(case["case_id"])
                continue
            label = report.labels[case["case_id"]]
            output = answer(case)
            row = score_case(
                {
                    "case_id": case["case_id"],
                    "category": case["category"],
                    "expected_state": label.expected_state,
                    "expected_documents": list(label.consensus_documents),
                    "expected_conflict_documents": list(label.conflict_documents),
                },
                output,
            )
            acceptable = set(label.acceptable_documents)
            row["unsupported_citations"] = sorted(set(output["cited_documents"]) - acceptable)
            row["citation_precision"] = (
                round(len(set(output["cited_documents"]) & acceptable) / len(output["cited_documents"]), 4)
                if output["cited_documents"]
                else (1.0 if not acceptable else 0.0)
            )
            rows.append(row)
            costs.append(float(output.get("cost_usd") or 0.0))
        for case in disagreements:
            if name in external and not model_transmission_permitted(suite, case):
                continue
            output = answer(case)
            disagreement_rows.append(
                {
                    "case_id": case["case_id"],
                    "state": output["state"],
                    "reviewer_states": list(report.labels[case["case_id"]].reviewer_states),
                    "avoided_confident_candidate": output["state"] != "CANDIDATE",
                }
            )
        summary = aggregate(rows) if rows else None
        if summary is not None:
            summary["provider_cost_usd"] = round(sum(costs), 6)
            summary["mean_cost_usd"] = round(statistics.mean(costs), 6)
        results[name] = {
            "summary": summary,
            "cases": rows,
            "skipped_for_rights": skipped,
            "disagreement_cases": disagreement_rows,
        }
    return {
        "status": "SCORED",
        "benchmark_version": BENCHMARK_VERSION,
        "split": split,
        "label_counts": report.counts(),
        "scorable_cases": len(scorable),
        "systems": results,
    }


def load_suite(directory: Path = REAL_BENCHMARK_DIR) -> dict[str, Any]:
    suite = json.loads((directory / "suite.json").read_text())
    for part in ("sources", "cases", "reviews"):
        path = directory / f"{part}.json"
        suite[part] = json.loads(path.read_text()) if path.exists() else []
    return suite
